exec tool declaration:
```ts
declare const tools: { mcp__pixellab__create_image_pro_flash(args: {
  description: string;
  height?: number;
  // At most this many colours in the image (2-64). With a palette, they are picked from it.
  max_colors?: number | null;
  no_background?: boolean;
  // Target palette, 2 to 256 hex colours as a JSON array, e.g. ["#081820", "#346856", "#88c070", "#e0f8d0"] for Game Boy or ["#000000", "#ffffff"] for 1-bit. The image is drawn for these colours and every pixel of the result is one of them.
  palette?: Array<string> | null;
  // Optional name of the palette (e.g. 'Game Boy', 'PICO-8'); naming it helps the look.
  palette_name?: string | null;
  project_id?: string | null;
  seed?: number;
  // Style anchor. Exactly ONE of its three sources: `url` also accepts an `upload:<id>` from get_upload_url or a data: URL, and `source_image_id` is an image you own (what a Pro Flash job returns). It must fit INSIDE the output canvas both ways — a larger one is refused, so crop it; resizing pixel art is never the answer. Reuse one anchor across calls to keep a set consistent.
  style_image?: {
  base64?: string | null;
  source_image_id?: string | null;
  url?: string | null;
  // How this reference should guide appearance.
  usage_description?: string | null;
} | null;
  // Choose which visual traits to copy from the style image.
  style_options?: { color_palette?: boolean; detail?: boolean; outline?: boolean; shading?: boolean; } | null;
  // Native sizes: 16x16 (experimental), 24x24, 32x32, 32x48, 48x48, 64x64, 96x64, 96x96, 128x128. Custom size (Beta): integer width 16–256 and height 16–256. Both dimensions must be multiples of 4 pixels. Pixel-grid recovery uses image-to-pixel-art with fixer when needed. No native image resizing.
  width?: number;
}): Promise<CallToolResult>; };
```
